using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public sealed class EvaluationTests
{
    private static DistributedApplication? _app;
    private static ReportingConfiguration? _reportingConfiguration;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        var appHost =
            await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();

        _app = await appHost.BuildAsync();
        await _app.StartAsync();

        _reportingConfiguration = CreateReportingConfiguration();
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        if (_app is not null)
        {
            await _app.StopAsync();
            await _app.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task RespondsToGreeting()
    {
        await using var scenarioRun =
            await _reportingConfiguration!.CreateScenarioRunAsync(nameof(RespondsToGreeting));

        var chatClient = GetChatClient();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how are you?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenarioRun.EvaluateAsync(messages);
    }

    [TestMethod]
    public async Task AnswersFactualQuestion()
    {
        await using var scenarioRun =
            await _reportingConfiguration!.CreateScenarioRunAsync(nameof(AnswersFactualQuestion));

        var chatClient = GetChatClient();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenarioRun.EvaluateAsync(messages);
    }

    private static IChatClient GetChatClient()
    {
        var connectionString = _app!.GetConnectionString("chat")
            ?? throw new InvalidOperationException("Could not find 'chat' connection string.");

        // Resolve the chat client from the app's service provider
        return _app.Services.GetRequiredService<IChatClient>();
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var reportDir = Path.Combine(
            Directory.GetCurrentDirectory(), "evaluation-reports");

        return DiskBasedReportingConfiguration.Create(
            storageRootDir: reportDir,
            evaluators:
            [
                new CoherenceEvaluator(),
                new FluencyEvaluator(),
                new RelevanceEvaluator()
            ],
            chatConfiguration: GetEvaluatorChatConfiguration());
    }

    private static ChatConfiguration GetEvaluatorChatConfiguration()
    {
        // The evaluator uses the same chat endpoint to judge responses.
        // In production, you may want a separate evaluator model.
        return new ChatConfiguration(
            chatClientFactory: _ => GetEvaluatorChatClient(),
            tokenCountingChatClientFactory: null);
    }

    private static IChatClient GetEvaluatorChatClient()
    {
        // Uses the same chat client from the app host for evaluation.
        return _app!.Services.GetRequiredService<IChatClient>();
    }
}

