     private static ReportingConfiguration? _reportingConfiguration;

     [ClassInitialize]
     public static void ClassInitialize(TestContext context)
     {
         _reportingConfiguration = CreateReportingConfiguration();
     }

     [TestMethod]
     public async Task RespondsToGreeting()
     {
         await using var scenarioRun =
             await _reportingConfiguration!.CreateScenarioRunAsync(nameof(RespondsToGreeting));

         var chatClient = CreateChatClient();

         var messages = new List<ChatMessage>
         {
             new(ChatRole.User, "Hello, how are you?")
         };

         var response = await chatClient.GetResponseAsync(messages);

         await scenarioRun.EvaluateAsync(messages, response);

         Assert.IsFalse(
             string.IsNullOrWhiteSpace(response.Text),
             "Response should not be empty.");
     }

     [TestMethod]
     public async Task AnswersFactualQuestion()
     {
         await using var scenarioRun =
             await _reportingConfiguration!.CreateScenarioRunAsync(nameof(AnswersFactualQuestion));

         var chatClient = CreateChatClient();

         var messages = new List<ChatMessage>
         {
             new(ChatRole.User, "What is the capital of France?")
         };

         var response = await chatClient.GetResponseAsync(messages);

         await scenarioRun.EvaluateAsync(messages, response);

         Assert.IsTrue(
             response.Text?.Contains("Paris", StringComparison.OrdinalIgnoreCase) == true,
             "Response should mention Paris.");
     }

     [TestMethod]
     public async Task HandlesMultiTurnConversation()
     {
         await using var scenarioRun =
             await _reportingConfiguration!.CreateScenarioRunAsync(nameof(HandlesMultiTurnConversation));

         var chatClient = CreateChatClient();

         var messages = new List<ChatMessage>
         {
             new(ChatRole.User, "I'm planning a trip to Japan. What cities should I visit?")
         };

         var firstResponse = await chatClient.GetResponseAsync(messages);
         messages.AddRange(firstResponse.Messages);

         messages.Add(new ChatMessage(ChatRole.User, "Tell me more about the first city you mentioned."));
         var response = await chatClient.GetResponseAsync(messages);

         await scenarioRun.EvaluateAsync(messages, response);

         Assert.IsFalse(
             string.IsNullOrWhiteSpace(response.Text),
             "Multi-turn response should not be empty.");
     }

     private static IChatClient CreateChatClient()
     {
         var endpoint = Environment.GetEnvironmentVariable("CHAT_ENDPOINT")
             ?? throw new InvalidOperationException(
                 "Set the CHAT_ENDPOINT environment variable to the Azure OpenAI endpoint URL.");

         var apiKey = Environment.GetEnvironmentVariable("CHAT_API_KEY")
             ?? throw new InvalidOperationException(
                 "Set the CHAT_API_KEY environment variable.");

         var model = Environment.GetEnvironmentVariable("CHAT_MODEL") ?? "gpt-4o";

         return new Azure.AI.OpenAI.AzureOpenAIClient(
                 new Uri(endpoint),
                 new System.ClientModel.ApiKeyCredential(apiKey))
             .GetChatClient(model)
             .AsIChatClient();
     }

     private static ReportingConfiguration CreateReportingConfiguration()
     {
         var reportDir = Path.Combine(
             Directory.GetCurrentDirectory(), "evaluation-reports");

         return DiskBasedReportingConfiguration.Create(
             storageRootPath: reportDir,
             evaluators:
             [
                 new CoherenceEvaluator(),
                 new FluencyEvaluator(),
                 new RelevanceEvaluator()
             ],
             chatConfiguration: new ChatConfiguration(CreateChatClient()));
     }
 }

